assert len(set(contexts))==len(set(questions))==3
for prose in choices.values(): assert len(set(prose))==3
for i in range(3):
 request={'model':'jev-latest','state':{'context':contexts[i]},'questions':{'alias_policy':{'type':'choice','instructions':questions[i],'criteria':{k:v[i] for k,v in choices.items()}}}}
 (out/f'request-{i+1}.json').write_text(json.dumps(request,indent=2)+'\n')
(out/'wording-audit.json').write_text(json.dumps({'distinct_all_explanatory_fields':True,'semantic_review':'Three rewrites preserve identical facts, constraints and the same three policy alternatives. Context, judgment instructions and every option description differ in full prose; technical identifiers and JSON schema stay stable. Choices are advice, not proof or guaranteed bias removal.'},indent=2)+'\n')
for i in range(3):
 req=urllib.request.Request('https://api.typesafe.ai/v1/systemone',data=(out/f'request-{i+1}.json').read_bytes(),headers={'Authorization':'Bearer '+os.environ['TYPESAFE_API_KEY'],'Content-Type':'application/json'})
 with urllib.request.urlopen(req,timeout=45) as response: result=json.load(response)
 (out/f'response-{i+1}.json').write_text(json.dumps(result,indent=2)+'\n')
 print(json.dumps({'round':i+1,'answers':result.get('answers')}),flush=True)
